    s2 = lines[1]
    virus = lines[2]

    m, n, v_len = len(s1), len(s2), len(virus)

    def get_k_after(current_k, char):
        """
        Using KMP transition, find the new match length after appending char.
        """
        while current_k > 0 and current_k >= v_len:
            current_k = pi[current_k - 1]
            if current_k >= v_len:
                break
        while current_k > 0 and virus[current_k] != char:
            current_k = pi[current_k - 1]
        if current_k < v_len and virus[current_k] == char:
            current_k += 1
        return current_k

    # Compute KMP pi table for virus
    pi = [0] * v_len
    j_pi = 0
    for idx in range(1, v_len):
        while j_pi > 0 and virus[j_pi] != virus[idx]:
            j_pi = pi[j_pi - 1]
        if virus[j_pi] == virus[idx]:
            j_pi += 1
        pi[idx] = j_pi

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(i, j, k):
        """
        Returns the maximum LCS length using s1[:i], s2[:j] with virus match state k
        """
        if i == 0 or j == 0:
            return 0

        res = 0

        # Option 1: skip s1[i-1]
        res = max(res, dp(i - 1, j, k))

        # Option 2: skip s2[j-1]
        res = max(res, dp(i, j - 1, k))

        # Option 3: take if characters match
        if s1[i - 1] == s2[j - 1]:
            new_k = get_k_after(k, s1[i - 1])
            if new_k < v_len:  # Valid, doesn't contain virus
                res = max(res, dp(i - 1, j - 1, new_k) + 1)

        return res

    @lru_cache(maxsize=None)
    def dp_reconstruction(i, j, k):
        """
        Rebuild the actual LCS string using recursion
        Returns the string for the optimal subsequence
        """
        if i == 0 or j == 0:
            return ""

        best = -1
        choice = None

        # Option 1: skip s1[i-1]
        sk1 = dp_reconstruction(i - 1, j, k)
        if len(sk1) > best:
            best = len(sk1)
            choice = ('skip_s1', None)
        elif len(sk1) == best:
            choice = ('skip_s1', None)

        # Option 2: skip s2[j-1]
        sk2 = dp_reconstruction(i, j - 1, k)
        if len(sk2) > best:
            best = len(sk2)
            choice = ('skip_s2', None)
        elif len(sk2) == best and choice[0] == 'skip_s1':
            # Keep tie-breaking
            choice = ('skip_s2', None)

        # Option 3: take if characters match
        if s1[i - 1] == s2[j - 1]:
            new_k = get_k_after(k, s1[i - 1])
            if new_k < v_len:
                sk3 = dp_reconstruction(i - 1, j - 1, new_k)
                if len(sk3) + 1 > best:
                    best = len(sk3) + 1
                    choice = ('take', new_k)
                elif len(sk3) + 1 == best:
                    pass  # Keep existing tie

        if choice[0] == 'take':
            char = s1[i - 1]
            return char + choice[1][0] if isinstance(choice[1][0], str) else char + dp_reconstruction(*choice[1])
        elif choice[0] == 'skip_s1':
            return dp_reconstruction(i - 1, j, k)
        elif choice[0] == 'skip_s2':
