        lambda x: x[1],
        lambda x: -x[0],
        lambda x: -x[1],
        lambda x: abs(x[0]),
        lambda x: abs(x[1]),
        lambda x: x[0] + x[1],
        lambda x: x[0] - x[1],
    ]

