            if curr in path_vis:
                cycle_start_idx = path_vis[curr]
                cycle_length = step - cycle_start_idx

                # Mark all nodes in the cycle
                for idx in range(cycle_start_idx, len(path)):
                    cycle_nodes[path[idx]] = True

                # Mark nodes that lead to this cycle
                for idx in range(0, cycle_start_idx):
                    cycle_nodes[path[idx]] = True
            else:
                # Reached a node already processed - mark all in current path
                for node in path:
                    cycle_nodes[node] = True

        # Count cycle nodes and black cells in cycles
        robots_max = sum(cycle_nodes)
        black_max = sum(cycle_nodes[i] and c[i // m][i % m] == '0' for i in range(nm))

        results.append(f"{robots_max} {black_max}")

    return '\n'.join(results)
