def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse table A (lines 1 to n)
    A = []
    for i in range(n):
        A.append(list(map(int, lines[i + 1].split())))

    # Parse table B (lines n+1 to 2n)
    B = []
    for i in range(n):
        B.append(list(map(int, lines[n + 1 + i].split())))

    # Check if row multisets match
    from collections import Counter
    a_rows = Counter(tuple(row) for row in A)
    b_rows = Counter(tuple(row) for row in B)

    if a_rows != b_rows:
        return '-1'

    # Check row ordering consistency
    # If two rows have the same values in A but different values in B,
    # stable sorting cannot handle this
    for i in range(n):
        for j in range(i + 1, n):
            if A[i] == A[j] and B[i] != B[j]:
                return '-1'

    # Try sorting by each column to see if we get B
    for col in range(1, m + 1):
        # Compute stable sorted order by this column
        order = sorted(range(n), key=lambda i: (A[i][col - 1], i))

        # Apply this ordering to A and check if it matches B
        sorted_A = [A[order[i]] for i in range(n)]

        if sorted_A == B:
            return str(1) + '\n' + str(col)

    # Try multiple columns sequentially
    result = []
    for length in range(1, 5000 + 1):
        # Try all combinations of columns of this length
        from itertools import combinations
        for cols in combinations(range(1, m + 1), length):
            test_A = [list(row) for row in A]

            # Apply sorting by each column in sequence
            for c in cols:
                order = sorted(range(n), key=lambda i: (test_A[i][c - 1], i))
                test_A = [test_A[order[i]] for i in range(n)]

                if test_A == B:
                    # Found solution
                    return str(len(cols)) + '\n' + ' '.join(map(str, cols))

            # Early exit if we've tried too many iterations
            if test_A == B:
                return str(len(cols)) + '\n' + ' '.join(map(str, cols))

