    p_set = set(p)
    parent = {x: x for x in p}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry

