        # Process sale days in order to maximize earnings
        # For each type, we can buy at sale price (cost=1) if there's a sale
        # Otherwise we must buy at regular price (cost=2)

        # Track what we can buy at each sale day
        sale_options = {}  # type -> sorted list of (day, count)

        for t in range(1, n + 1):
