        count_bought = 0
        total_cost = 0

        # Process day by day
        for day in range(1, D + 1):
            # Find all types on sale today
            on_sale = []
            for t in range(1, n + 1):
                if day in sales.get(t, []):
                    on_sale.append(t)

            # On each sale day, buy priority items
            for t in sorted(on_sale):
                ki = k[t - 1]
                if ki > 0:
                    remaining = ki - (day - 1)  # items already bought
                    remaining = max(0, remaining)
                    total_cost += remaining
                    ki -= remaining
                    for _ in range(remaining):
                        ki -= 1

        return total_cost <= D

    # Binary search for the minimum day
