import re
import sys

def get_valid_set_scores_for_winner(a_total, b_total):
    """Generate all valid set scores when team A wins a set."""
    valid_score_pairs = []

    for a_in_set in range(25, a_total + 1):
        # At deuce (24-24), need 2 point lead
        # Before deuce, can win at 25-x where x <= 24
        for b_in_set in range(a_in_set - 2, 25):
            if b_in_set < 25 and a_in_set >= 25 and a_in_set - b_in_set >= 2:
                if b_in_set < 25:
                    valid_score_pairs.append((a_in_set, b_in_set))

    return valid_score_pairs

def generate_sets(WA, WB, a, b):
    """Generate all valid set configurations for given match score."""
    n = WA + WB

    def backtrack(idx, a_rem, b_rem, wins_a, wins_b, current_sets):
        if idx == n:
            if a_rem == 0 and b_rem == 0:
                return [current_sets]
            return []

        results = []

        # Team A wins this set
        for sa, sb in generate_valid_set_scores_for_winner(a_total, b_total):
            if sa <= a_rem and sb <= b_rem and wins_a < WA:
                new_sets = current_sets + [(sa, sb)]
                res = backtrack(idx + 1, a_rem - sa, b_rem - sb, wins_a + 1, wins_b, new_sets)
                if res:
                    results.extend(res)

        # Team B wins this set
        for sb, sa in generate_valid_set_scores_for_loser(b_total, a_total):
            if sa <= a_rem and sb <= b_rem and wins_b < WB:
                new_sets = current_sets + [(sa, sb)]
                res = backtrack(idx + 1, a_rem - sa, b_rem - sb, wins_a, wins_b + 1, new_sets)
                if res:
                    results.extend(res)

        return results

    return backtrack(0, a, b, 0, 0, [])

